mapper.select:
SELECT d.dong_code AS dongCode, d.sido_name AS sidoName, d.gugun_name AS gugunName, d.dong_name AS dongName, COUNT(s.school_id) AS schoolCount FROM dongcodes d LEFT JOIN schools s ON s.dong_code = d.dong_code AND s.operation_status = '운영' WHERE d.dong_code IN
#{dongCode}
GROUP BY d.dong_code, d.sido_name, d.gugun_name, d.dong_name ORDER BY d.dong_code
